CREATE TABLE den_profiles(user_id TEXT PRIMARY KEY REFERENCES den_users(id),display_name TEXT NOT NULL,phone TEXT NOT NULL DEFAULT '');
CREATE TABLE den_addresses(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES den_users(id),label TEXT NOT NULL,address TEXT NOT NULL,country TEXT NOT NULL REFERENCES den_countries(code));
CREATE TABLE den_organizations(id TEXT PRIMARY KEY,owner_id TEXT NOT NULL REFERENCES den_users(id),name TEXT NOT NULL,country TEXT NOT NULL REFERENCES den_countries(code),status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','rejected','suspended')),created_at INTEGER NOT NULL);
CREATE TABLE den_riders(user_id TEXT PRIMARY KEY REFERENCES den_users(id),vehicle TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','rejected','suspended')),created_at INTEGER NOT NULL);
CREATE TABLE den_products(id TEXT PRIMARY KEY,organization_id TEXT NOT NULL REFERENCES den_organizations(id),name TEXT NOT NULL,price_minor INTEGER NOT NULL CHECK(price_minor>0),currency TEXT NOT NULL CHECK(length(currency)=3),stock INTEGER NOT NULL CHECK(stock>=0),active INTEGER NOT NULL DEFAULT 1 CHECK(active IN(0,1)));
CREATE TABLE den_cart(user_id TEXT NOT NULL REFERENCES den_users(id),product_id TEXT NOT NULL REFERENCES den_products(id),quantity INTEGER NOT NULL CHECK(quantity BETWEEN 1 AND 100),PRIMARY KEY(user_id,product_id));
CREATE TABLE den_orders(id TEXT PRIMARY KEY,consumer_id TEXT NOT NULL REFERENCES den_users(id),organization_id TEXT NOT NULL REFERENCES den_organizations(id),rider_id TEXT REFERENCES den_users(id),address TEXT NOT NULL,state TEXT NOT NULL DEFAULT 'placed' CHECK(state IN('placed','reserved','picked_up','delivered')),ready INTEGER NOT NULL DEFAULT 0,org_scanned INTEGER NOT NULL DEFAULT 0,handoff INTEGER NOT NULL DEFAULT 0,product_total INTEGER NOT NULL CHECK(product_total>0),currency TEXT NOT NULL,product_payment TEXT NOT NULL CHECK(product_payment='sandbox_digital_paid'),delivery_payment TEXT NOT NULL CHECK(delivery_payment IN('cash_due','cash_confirmed','sandbox_digital_due','sandbox_digital_paid')),cash_hash TEXT,delivery_hash TEXT NOT NULL,pickup_token TEXT NOT NULL,completion_token TEXT,qr_expires_at INTEGER,code_verified INTEGER NOT NULL DEFAULT 0,created_at INTEGER NOT NULL,delivered_at INTEGER);
CREATE TABLE den_order_lines(order_id TEXT NOT NULL REFERENCES den_orders(id),product_id TEXT NOT NULL REFERENCES den_products(id),name TEXT NOT NULL,quantity INTEGER NOT NULL,unit_price INTEGER NOT NULL,PRIMARY KEY(order_id,product_id));
CREATE TABLE den_order_secrets(order_id TEXT PRIMARY KEY REFERENCES den_orders(id),delivery_code TEXT NOT NULL,cash_code TEXT);
CREATE TABLE den_notifications(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES den_users(id),message TEXT NOT NULL,created_at INTEGER NOT NULL);
CREATE INDEX den_orders_consumer ON den_orders(consumer_id,created_at);
CREATE INDEX den_orders_rider ON den_orders(rider_id,state);
CREATE INDEX den_products_org ON den_products(organization_id);
CREATE TRIGGER den_no_manager_rider BEFORE INSERT ON den_riders WHEN EXISTS(SELECT 1 FROM den_organizations WHERE owner_id=NEW.user_id) BEGIN SELECT RAISE(ABORT,'MANAGER_RIDER_CONFLICT'); END;
CREATE TRIGGER den_no_rider_manager BEFORE INSERT ON den_organizations WHEN EXISTS(SELECT 1 FROM den_riders WHERE user_id=NEW.owner_id) BEGIN SELECT RAISE(ABORT,'MANAGER_RIDER_CONFLICT'); END;
